cssSegments.0f1986e7979faff0:
@media (prefers-reduced-motion: no-preference){
  .home-lint[data-phase="scan"] .home-lint-beam {
    animation: 1s linear both home-lint-scan;
  }

  .home-lint[data-phase="fixed"] .home-lint-beam {
    animation: .6s linear .1s both home-lint-scan;
  }

  .home-lint[data-phase="report"] [data-problem] .home-lint-glyph:after {
    animation: .9s ease-out .2s both home-lint-ring;
  }

  .home-lint[data-phase="scan"] .home-lint-source[data-active] .home-lint-token {
    animation: .5s ease-out both home-lint-read;
    animation-delay: calc(var(--column) / var(--home-lint-columns) * 1s - 80ms);
  }

  .home-lint[data-phase="report"] .home-lint-token[data-marked]:after {
    animation-name: home-lint-squiggle;
    animation-duration: .32s;
    animation-timing-function: var(--home-ease);
    animation-delay: calc((var(--column) - 1) * 4ms);
    animation-fill-mode: both;
  }

  .home-lint[data-reported] :is([data-active], .home-lint-range) .home-lint-loc {
    animation-name: home-lint-lit;
    animation-duration: 2.2s;
    animation-timing-function: var(--home-ease);
    animation-fill-mode: both;
  }

  .home-lint-problem[data-shown] .home-lint-problem-icon {
    animation-name: home-lint-pop;
    animation-duration: .42s;
    animation-timing-function: var(--home-ease);
    animation-fill-mode: both;
  }

  [data-state="lit"] [data-active] .home-lint-out {
    animation-name: home-lint-print;
    animation-duration: .42s;
    animation-timing-function: var(--home-ease);
    animation-delay: calc(var(--i) * 70ms + .12s);
    animation-fill-mode: both;
  }

  .home-lint[data-phase="report"] .home-lint-problems:before, [data-state="lit"] > .home-lint-pane-bar:after {
    animation-name: home-lint-pulse;
    animation-duration: 1.1s;
    animation-timing-function: var(--home-ease-inout);
    animation-fill-mode: both;
  }

  [data-state="running"] [data-active] .home-lint-command:after {
    vertical-align: -.2em;
    background-color: var(--home-text-quiet);
    content: "";
    width: .5em;
    height: 1.1em;
    margin-inline: .25em -.75em;
    animation: .8s step-end infinite home-lint-caret;
    display: inline-block;
  }
}

