  svg { flex: none; }
  .demo-change { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 26px; padding-top: 18px; border-top: 1px solid var(--demo-line); }
  .change-class { display: flex; align-items: center; gap: 7px; min-width: 0; font-size: 10px; }
  .change-class code { font-family: var(--home-mono); }
